80	thread::hardware_concurrency() noexcept
81	{
82	#if defined(_SC_NPROCESSORS_ONLN)
83	    long result = sysconf(_SC_NPROCESSORS_ONLN);
84	    // sysconf returns -1 if the name is invalid, the option does not exist or
85	    // does not have a definite limit.
86	    // if sysconf returns some other negative number, we have no idea
87	    // what is going on. Default to something safe.
88	    if (result < 0)
89	        return 0;
90	    return static_cast<unsigned>(result);
91	#elif defined(_LIBCPP_WIN32API)
92	    SYSTEM_INFO info;
93	    GetSystemInfo(&info);
94	    return info.dwNumberOfProcessors;
95	#else  // defined(CTL_HW) && defined(HW_NCPU)
96	    // TODO: grovel through /proc or check cpuid on x86 and similar
97	    // instructions on other architectures.
98	#   if defined(_LIBCPP_WARNING)
99	        _LIBCPP_WARNING("hardware_concurrency not yet implemented")
100	#   else
101	#       warning hardware_concurrency not yet implemented
102	#   endif
103	    return 0;  // Means not computable [thread.thread.static]
104	#endif // defined(CTL_HW) && defined(HW_NCPU)
