146	static void __libcpp_contention_notify(__cxx_atomic_contention_t volatile* __contention_state,
147	                                       __cxx_atomic_contention_t const volatile* __platform_state,
148	                                       bool __notify_one)
149	{
150	    if(0 != __cxx_atomic_load(__contention_state, memory_order_seq_cst))
151	        // We only call 'wake' if we consumed a contention bit here.
152	        __libcpp_platform_wake_by_address(__platform_state, __notify_one);
153	}
154	static __cxx_contention_t __libcpp_contention_monitor_for_wait(__cxx_atomic_contention_t volatile* __contention_state,
155	                                                               __cxx_atomic_contention_t const volatile* __platform_state)
156	{
157	    // We will monitor this value.
158	    return __cxx_atomic_load(__platform_state, memory_order_acquire);
159	}
160	static void __libcpp_contention_wait(__cxx_atomic_contention_t volatile* __contention_state,
161	                                     __cxx_atomic_contention_t const volatile* __platform_state,
162	                                     __cxx_contention_t __old_value)
163	{
164	    __cxx_atomic_fetch_add(__contention_state, __cxx_contention_t(1), memory_order_seq_cst);
165	    // We sleep as long as the monitored value hasn't changed.
166	    __libcpp_platform_wait_on_address(__platform_state, __old_value);
167	    __cxx_atomic_fetch_sub(__contention_state, __cxx_contention_t(1), memory_order_release);
168	}
