170	/* When the incoming atomic is the wrong size for the platform wait size, need to
171	   launder the value sequence through an atomic from our table. */
172	
173	static void __libcpp_atomic_notify(void const volatile* __location)
174	{
175	    auto const __entry = __libcpp_contention_state(__location);
176	    // The value sequence laundering happens on the next line below.
177	    __cxx_atomic_fetch_add(&__entry->__platform_state, __cxx_contention_t(1), memory_order_release);
178	    __libcpp_contention_notify(&__entry->__contention_state,
179	                               &__entry->__platform_state,
180	                               false /* when laundering, we can't handle notify_one */);
181	}
182	_LIBCPP_EXPORTED_FROM_ABI
183	void __cxx_atomic_notify_one(void const volatile* __location)
184	    { __libcpp_atomic_notify(__location); }
185	_LIBCPP_EXPORTED_FROM_ABI
186	void __cxx_atomic_notify_all(void const volatile* __location)
187	    { __libcpp_atomic_notify(__location); }
188	_LIBCPP_EXPORTED_FROM_ABI
189	__cxx_contention_t __libcpp_atomic_monitor(void const volatile* __location)
190	{
191	    auto const __entry = __libcpp_contention_state(__location);
192	    return __libcpp_contention_monitor_for_wait(&__entry->__contention_state, &__entry->__platform_state);
193	}
194	_LIBCPP_EXPORTED_FROM_ABI
195	void __libcpp_atomic_wait(void const volatile* __location, __cxx_contention_t __old_value)
196	{
197	    auto const __entry = __libcpp_contention_state(__location);
198	    __libcpp_contention_wait(&__entry->__contention_state, &__entry->__platform_state, __old_value);
199	}
