201	/* When the incoming atomic happens to be the platform wait size, we still need to use the
202	   table for the contention detection, but we can use the atomic directly for the wait. */
203	
204	_LIBCPP_EXPORTED_FROM_ABI
205	void __cxx_atomic_notify_one(__cxx_atomic_contention_t const volatile* __location)
206	{
207	    __libcpp_contention_notify(&__libcpp_contention_state(__location)->__contention_state, __location, true);
208	}
