35	 * Private Functions
36	 ****************************************************************************/
37	
38	/****************************************************************************
39	 * Name: stdoutstream_putc
40	 ****************************************************************************/
41	
42	static void stdoutstream_putc(FAR struct lib_outstream_s *self, int ch)
43	{
44	  FAR struct lib_stdoutstream_s *stream =
45	                                      (FAR struct lib_stdoutstream_s *)self;
46	  int result;
47	
48	  DEBUGASSERT(self && stream->handle);
49	
50	  /* Loop until the character is successfully transferred or an irrecoverable
51	   * error occurs.
52	   */
53	
54	  do
55	    {
56	      result = fputc(ch, stream->handle);
57	      if (result != EOF)
58	        {
59	          self->nput++;
60	          return;
61	        }
62	
63	      /* EINTR (meaning that fputc was interrupted by a signal) is the only
64	       * recoverable error.
65	       */
66	    }
67	  while (get_errno() == EINTR);
68	}
69	
70	/****************************************************************************
71	 * Name: stdoutstream_puts
72	 ****************************************************************************/
73	
74	static ssize_t stdoutstream_puts(FAR struct lib_outstream_s *self,
75	                                 FAR const void *buffer, size_t len)
76	{
77	  FAR struct lib_stdoutstream_s *stream =
78	                               (FAR struct lib_stdoutstream_s *)self;
79	  ssize_t result;
80	
81	  DEBUGASSERT(self && stream->handle);
82	
83	  /* Loop until the buffer is successfully transferred or an irrecoverable
84	   * error occurs.
85	   */
86	
87	  do
88	    {
89	      result = fwrite(buffer, 1, len, stream->handle);
90	      if (result >= 0)
91	        {
92	          self->nput += result;
93	          return result;
94	        }
95	
96	      result = _NX_GETERRVAL(result);
97	
98	      /* EINTR (meaning that fputc was interrupted by a signal) is the only
99	       * recoverable error.
100	       */
101	    }
102	  while (result == -EINTR);
103	
104	  return result;
105	}
106	
107	/****************************************************************************
108	 * Name: stdoutstream_flush
109	 ****************************************************************************/
110	
111	#ifndef CONFIG_STDIO_DISABLE_BUFFERING
112	static int stdoutstream_flush(FAR struct lib_outstream_s *self)
113	{
114	  FAR struct lib_stdoutstream_s *stream =
115	                                (FAR struct lib_stdoutstream_s *)self;
116	
117	  DEBUGASSERT(stream != NULL && stream->handle != NULL);
118	  return lib_fflush(stream->handle);
119	}
120	#endif
121	
122	/****************************************************************************
123	 * Public Functions
124	 ****************************************************************************/
125	
126	/****************************************************************************
127	 * Name: lib_stdoutstream
128	 *
129	 * Description:
130	 *   Initializes a stream for use with a FILE instance.
131	 *
132	 * Input Parameters:
133	 *   outstream - User allocated, uninitialized instance of struct
134	 *               lib_stdoutstream_s to be initialized.
135	 *   handle    - User provided FILE instance (must have been opened for
136	 *               write access).
137	 *
138	 * Returned Value:
139	 *   None (User allocated instance initialized).
140	 *
141	 ****************************************************************************/
142	
143	void lib_stdoutstream(FAR struct lib_stdoutstream_s *stream,
144	                      FAR FILE *handle)
145	{
146	  /* Select the putc operation */
147	
148	  stream->common.putc = stdoutstream_putc;
149	  stream->common.puts = stdoutstream_puts;
150	
151	  /* Select the correct flush operation.  This flush is only called when
152	   * a newline is encountered in the output file stream.  However, we do not
153	   * want to support this line buffering behavior if the file was
154	   * opened in binary mode.  In binary mode, the newline has no special
155	   * meaning.
156	   */
157	
158	#ifndef CONFIG_STDIO_DISABLE_BUFFERING
159	  if (handle->fs_bufstart != NULL && (handle->fs_oflags & O_TEXT) != 0)
160	    {
161	      stream->common.flush = stdoutstream_flush;
162	    }
163	  else
164	#endif
165	    {
166	      stream->common.flush = lib_noflush;
167	    }
168	
169	  /* Set the number of bytes put to zero and remember the handle */
170	
171	  stream->common.nput = 0;
172	  stream->handle      = handle;
173	}
