57	#define OPTARG_TO_VALUE(value, type, base)                            \
58	  do                                                                  \
59	    {                                                                 \
60	      FAR char *ptr;                                                  \
61	      value = (type)strtoul(optarg, &ptr, base);                      \
62	      if (*ptr != '\0')                                               \
63	        {                                                             \
64	          printf("Parameter error: -%c %s\n", ch, optarg);            \
65	          show_usage(argv[0], rtc_state, EXIT_FAILURE);               \
66	        }                                                             \
67	    } while (0)
