85	/****************************************************************************
86	 * Name: show_usage
87	 ****************************************************************************/
88	
89	static void show_usage(FAR const char *progname,
90	                       FAR struct rtc_state_s *rtc_state, int exitcode)
91	{
92	  printf("Usage: %s -d <devpath> -a <deviation> -v <delay>\n", progname);
93	  printf("  [-d devpath] selects the rtc device.\n"
94	         "  Default: %s Current: %s\n", RTC_DEFAULT_DEVPATH,
95	         rtc_state->devpath);
96	  printf("  [-a deviation] input rtc alarm .\n"
97	         "  Default: %d Current: %d\n", RTC_DEFAULT_DEVIATION,
98	         rtc_state->deviation);
99	  printf("  [-v delay] delay after set rtc.\n"
100	         "  Default: %d Current: %d\n", VENDOR_DELAY,
101	         rtc_state->vendor_delay);
102	  exit(exitcode);
103	}
