105	/****************************************************************************
106	 * Name: parse_commandline
107	 ****************************************************************************/
108	
109	static void parse_commandline(FAR struct rtc_state_s *rtc_state, int argc,
110	                              FAR char **argv)
111	{
112	  int ch;
113	  int converted;
114	
115	  while ((ch = getopt(argc, argv, "d:a:v:")) != ERROR)
116	    {
117	      switch (ch)
118	        {
119	          case 'd':
120	            strlcpy(rtc_state->devpath, optarg, sizeof(rtc_state->devpath));
121	            break;
122	
123	          case 'a':
124	            OPTARG_TO_VALUE(converted, int, 10);
125	            rtc_state->deviation = converted;
126	            if (converted < 0)
127	              {
128	                printf("deviation out of range: %d\n", converted);
129	                show_usage(argv[0], rtc_state, EXIT_FAILURE);
130	              }
131	            break;
132	
133	          case 'v':
134	            OPTARG_TO_VALUE(converted, int, 10);
135	            rtc_state->vendor_delay = converted;
136	            if (converted < 0)
137	              {
138	                printf("delay out of range: %d\n", converted);
139	                show_usage(argv[0], rtc_state, EXIT_FAILURE);
140	              }
141	            break;
142	
143	          case '?':
144	            printf("Unsupported option: %s\n", optarg);
145	            show_usage(argv[0], rtc_state, EXIT_FAILURE);
146	        }
147	    }
148	}
