150	/****************************************************************************
151	 * Name: drivertest_rtc_api
152	 ****************************************************************************/
153	
154	static void drivertest_rtc_api(FAR void **state)
155	{
156	  int fd;
157	  int ret;
158	  bool have_set_time;
159	  char timbuf[64];
160	  int success_count = 0;
161	  struct rtc_time set_time;
162	  struct rtc_time rd_time;
163	  FAR struct rtc_state_s *rtc_state;
164	
165	  rtc_state = (FAR struct rtc_state_s *)*state;
166	
167	  fd = open(rtc_state->devpath, O_WRONLY);
168	  assert_return_code(fd, 0);
169	
170	  memset(&set_time, 0, sizeof(set_time));
171	  set_time.tm_year = 2000 - TM_YEAR_BASE;
172	  set_time.tm_mon = TM_JANUARY;
173	  set_time.tm_mday = 1;
174	  set_time.tm_wday = TM_SATURDAY;
175	
176	  for (int i = 0; i < 5; i++)
177	    {
178	      ret = ioctl(fd, RTC_SET_TIME, (unsigned long)((uintptr_t)&set_time));
179	      assert_return_code(ret, OK);
180	
181	      ret = ioctl(fd, RTC_HAVE_SET_TIME,
182	                  (unsigned long)((uintptr_t)&have_set_time));
183	      assert_return_code(ret, OK);
184	
185	      /* Some vendor need sleep a period of time
186	       * after set rtc because of hardware bug.
187	       */
188	
189	      sleep(rtc_state->vendor_delay);
190	
191	      assert_true(have_set_time);
192	
193	      ret = ioctl(fd, RTC_RD_TIME, (unsigned long)((uintptr_t)&rd_time));
194	      assert_return_code(ret, OK);
195	
196	      if (set_time.tm_year == rd_time.tm_year &&
197	          set_time.tm_mon == rd_time.tm_mon &&
198	          set_time.tm_mday == rd_time.tm_mday &&
199	          set_time.tm_wday == rd_time.tm_wday)
200	        {
201	          success_count++;
202	        }
203	    }
204	
205	  assert_true(success_count >= 3);
206	
207	  ret = strftime(timbuf, sizeof(timbuf), "%a, %b %d %H:%M:%S %Y",
208	                 (FAR struct tm *)&rd_time);
209	  assert_return_code(ret, OK);
210	
211	  close(fd);
212	}
