215	/****************************************************************************
216	 * Name: get_timestamp
217	 ****************************************************************************/
218	
219	static uint32_t get_timestamp(void)
220	{
221	  struct timespec ts;
222	  uint32_t ms;
223	  clock_gettime(CLOCK_MONOTONIC, &ts);
224	  ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
225	  return ms;
226	}
227	#endif
