230	/****************************************************************************
231	 * Name: add_timeout
232	 ****************************************************************************/
233	
234	static void add_timeout(struct rtc_time * rtc_tm, const int delay)
235	{
236	  time_t timesp;
237	  FAR struct tm *tm;
238	
239	  timesp = timegm((struct tm *)rtc_tm);
240	  timesp += delay;
241	
242	  tm = gmtime(&timesp);
243	  rtc_tm->tm_sec = tm->tm_sec;
244	  rtc_tm->tm_min = tm->tm_min;
245	  rtc_tm->tm_hour = tm->tm_hour;
246	  rtc_tm->tm_mday = tm->tm_mday;
247	  rtc_tm->tm_mon = tm->tm_mon;
248	  rtc_tm->tm_year = tm->tm_year;
249	  rtc_tm->tm_wday = tm->tm_wday;
250	  rtc_tm->tm_yday = tm->tm_yday;
251	  rtc_tm->tm_isdst = tm->tm_isdst;
252	}
