254	/****************************************************************************
255	 * Name: drivertest_rtc_alarm
256	 ****************************************************************************/
257	
258	static void drivertest_rtc_alarm(FAR void **state)
259	{
260	  int fd;
261	  int ret;
262	  int alarmid = 0;
263	  struct rtc_setalarm_s rtc_setalarm;
264	  struct rtc_rdalarm_s rtc_rdalarm;
265	  struct rtc_setrelative_s rtc_setrelative;
266	  struct rtc_time set_time;
267	  uint32_t before_timestamp;
268	  uint32_t range;
269	  sigset_t set;
270	  FAR struct rtc_state_s *rtc_state =
271	                  (FAR struct rtc_state_s *)*state;
272	
273	  signal(RTC_SIGNO, SIG_IGN);
274	  sigemptyset(&set);
275	  sigaddset(&set, RTC_SIGNO);
276	
277	  fd = open(rtc_state->devpath, O_RDWR);
278	  assert_return_code(fd, 0);
279	
280	  memset(&set_time, 0, sizeof(set_time));
281	  set_time.tm_year = 2000 - TM_YEAR_BASE;
282	  set_time.tm_mon = TM_JANUARY;
283	  set_time.tm_mday = 1;
284	  set_time.tm_wday = TM_SATURDAY;
285	
286	  /* Set rtc alarm */
287	
288	  rtc_setalarm.id = 0;
289	  rtc_setalarm.pid = getpid();
290	  rtc_setalarm.event.sigev_notify = SIGEV_SIGNAL;
291	  rtc_setalarm.event.sigev_signo = RTC_SIGNO;
292	  rtc_setalarm.event.sigev_value.sival_ptr = NULL;
293	  rtc_setalarm.time = set_time;
294	
295	  add_timeout(&rtc_setalarm.time, DEFAULT_TIME_OUT);
296	
297	  ret = ioctl(fd, RTC_SET_TIME, (unsigned long)((uintptr_t)&set_time));
298	  assert_return_code(ret, OK);
299	
300	  sleep(rtc_state->vendor_delay);
301	  add_timeout(&rtc_setalarm.time, rtc_state->vendor_delay);
302	
303	  ret = ioctl(fd, RTC_SET_ALARM, &rtc_setalarm);
304	  assert_return_code(ret, OK);
305	
306	  before_timestamp = get_timestamp();
307	  sleep(rtc_state->vendor_delay);
308	
309	  /* Read alarm */
310	
311	  rtc_rdalarm.id = 0;
312	  ret = ioctl(fd, RTC_RD_ALARM, &rtc_rdalarm);
313	  assert_return_code(ret, OK);
314	
315	  assert_int_equal(timegm((struct tm *)&rtc_rdalarm.time),
316	                   timegm((struct tm *)&rtc_setalarm.time));
317	
318	  ret = sigwaitinfo(&set, NULL);
319	  assert_return_code(ret, RTC_SIGNO);
320	
321	  range = abs(get_timestamp() - before_timestamp);
322	  assert_in_range(range, DEFAULT_TIME_OUT * 1000 - rtc_state->deviation,
323	                  DEFAULT_TIME_OUT * 1000 + rtc_state->deviation);
324	
325	  /* Cancel rtc alarm */
326	
327	  ret = ioctl(fd, RTC_SET_TIME, (unsigned long)((uintptr_t)&set_time));
328	  assert_return_code(ret, OK);
329	
330	  sleep(rtc_state->vendor_delay);
331	
332	  rtc_setalarm.time = set_time;
333	  add_timeout(&rtc_setalarm.time, DEFAULT_TIME_OUT);
334	
335	  ret = ioctl(fd, RTC_SET_ALARM, &rtc_setalarm);
336	  assert_return_code(ret, OK);
337	
338	  ret = ioctl(fd, RTC_CANCEL_ALARM, alarmid);
339	  assert_return_code(ret, OK);
340	
341	  /* Set relative */
342	
343	  rtc_setrelative.id = 0;
344	  rtc_setrelative.pid = getpid();
345	  rtc_setrelative.event.sigev_notify = SIGEV_SIGNAL;
346	  rtc_setrelative.event.sigev_signo = RTC_SIGNO;
347	  rtc_setrelative.event.sigev_value.sival_ptr = NULL;
348	  rtc_setrelative.reltime = DEFAULT_TIME_OUT;
349	
350	  ret = ioctl(fd, RTC_SET_RELATIVE, &rtc_setrelative);
351	  assert_return_code(ret, OK);
352	
353	  before_timestamp = get_timestamp();
354	
355	  ret = sigwaitinfo(&set, NULL);
356	  assert_return_code(ret, RTC_SIGNO);
357	
358	  range = abs(get_timestamp() - before_timestamp);
359	  assert_in_range(range, DEFAULT_TIME_OUT * 1000 - rtc_state->deviation,
360	                  DEFAULT_TIME_OUT * 1000 + rtc_state->deviation);
361	  close(fd);
362	}
363	#endif
