365	#ifdef CONFIG_RTC_PERIODIC
366	/****************************************************************************
367	 * Name: rtc_periodic_callback
368	 ****************************************************************************/
369	
370	static void rtc_periodic_callback(union sigval arg)
371	{
372	  FAR struct rtc_state_s * rtc_state =
373	    (FAR struct rtc_state_s *)arg.sival_ptr;
374	  int range = get_timestamp() - rtc_state->tim;
375	  assert_in_range(range, DEFAULT_TIME_OUT * 1000 - rtc_state->deviation,
376	                  DEFAULT_TIME_OUT * 1000 + rtc_state->deviation);
377	  syslog(LOG_DEBUG, "rtc periodic callback trigger!!!\n");
378	  rtc_state->tim = get_timestamp();
379	}
380	
381	/****************************************************************************
382	 * Name: drivertest_rtc_periodic
383	 ****************************************************************************/
384	
385	static void drivertest_rtc_periodic(FAR void **state)
386	{
387	  int alarmid = 0;
388	  int ret;
389	  int fd;
390	  struct rtc_setperiodic_s rtc_setperiodic;
391	  FAR struct rtc_state_s *rtc_state =
392	                  (FAR struct rtc_state_s *)*state;
393	
394	  fd = open(rtc_state->devpath, O_RDWR);
395	  assert_return_code(fd, OK);
396	
397	  /* Set periodic */
398	
399	  rtc_setperiodic.id = 0;
400	  rtc_setperiodic.pid = getpid();
401	  rtc_setperiodic.event.sigev_notify = SIGEV_THREAD;
402	  rtc_setperiodic.event.sigev_notify_function = rtc_periodic_callback;
403	  rtc_setperiodic.event.sigev_notify_attributes = NULL;
404	  rtc_setperiodic.event.sigev_value.sival_ptr = rtc_state;
405	  rtc_setperiodic.period.tv_sec = DEFAULT_TIME_OUT;
406	  rtc_setperiodic.period.tv_nsec = 0;
407	
408	  ret = ioctl(fd, RTC_SET_PERIODIC, &rtc_setperiodic);
409	  assert_return_code(ret, OK);
410	  rtc_state->tim = get_timestamp();
411	  sleep(SLEEPSECONDS);
412	
413	  /* Cancel periodic */
414	
415	  ret = ioctl(fd, RTC_CANCEL_PERIODIC, alarmid);
416	  assert_return_code(ret, OK);
417	
418	  sleep(SLEEPSECONDS);
419	  close(fd);
420	}
421	#endif
