205	static void ls2k300_rtc_hw_init(FAR struct ls2k300_rtc_lowerhalf_s *priv)
206	{
207	  uint32_t ctrl;
208	
209	  rtc_putreg(priv, LS2K300_RTC_TOY_TRIM_REG, 0x0);
210	  rtc_putreg(priv, LS2K300_RTC_TRIM_REG, 0x0);
211	
212	  ctrl = rtc_getreg(priv, LS2K300_RTC_CTRL_REG);
213	  ctrl |= RTC_CTRL_TOY_ENABLE_BIT | RTC_CTRL_OSC_ENABLE_BIT;
214	  rtc_putreg(priv, LS2K300_RTC_CTRL_REG, ctrl);
215	}
