217	int ls2k300_rtc_initialize(void)
218	{
219	  FAR struct rtc_lowerhalf_s *lower;
220	  int ret;
221	
222	  ls2k300_rtc_hw_init(&g_rtc_lowerhalf);
223	
224	  lower = (FAR struct rtc_lowerhalf_s *)&g_rtc_lowerhalf;
225	  up_rtc_set_lowerhalf(lower, true);
226	
227	  ret = rtc_initialize(0, lower);
228	  if (ret < 0)
229	    {
230	      rtcerr("ERROR: rtc_initialize failed: %d\n", ret);
231	      return ret;
232	    }
233	
234	  return OK;
235	}
