346	#ifdef CONFIG_LS2K300_SPIIO2
347	  /* SPIIO2 SPI Flash init: after pinctrl and GPIO are ready.
348	   * GPIO85 pinmux was blind-written in hardware_init(); re-assert here
349	   * because ls2k300_gpio_initialize() resets all pins to GPIO_INPUT_PIN.
350	   */
351	
352	  {
353	    uintptr_t gpio_base = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE);
354	
355	    /* Blind-write pinmux again (GPIO init may have RMW'd it) */
356	
357	    *(volatile uint32_t *)PHYS_TO_UNCACHED(0x160004A4) = 0xFFFEF3FF;
358	
359	    /* DIR=0 (output), OUT=1 (CS idle high) */
360	
361	    writeb(0, (volatile void *)(gpio_base + 0x800 + 85));
362	    writeb(1, (volatile void *)(gpio_base + 0x900 + 85));
363	  }
364	
365	  _info("bringup: SPIIO2 SPI Flash\n");
366	  {
367	    FAR struct spi_dev_s *spi = ls2k300_spiio_initialize(0);
368	    if (spi == NULL)
369	      {
370	        serr("ERROR: ls2k300_spiio_initialize failed for SPIIO2\n");
371	      }
372	    else
373	      {
374	        /* Software reset flash chip (recover from stale state) */
375	
376	        SPI_SELECT(spi, SPIDEV_FLASH(0), true);
377	        SPI_SEND(spi, 0x66);  /* Enable Reset */
378	        SPI_SELECT(spi, SPIDEV_FLASH(0), false);
379	        up_udelay(1);
380	
381	        SPI_SELECT(spi, SPIDEV_FLASH(0), true);
382	        SPI_SEND(spi, 0x99);  /* Reset */
383	        SPI_SELECT(spi, SPIDEV_FLASH(0), false);
384	        up_mdelay(30);
385	
386	        /* Probe GD25 flash */
387	
388	        FAR struct mtd_dev_s *mtd = gd25_initialize(spi, 0);
389	        if (mtd == NULL)
390	          {
391	            serr("ERROR: gd25_initialize failed on SPIIO2\n");
392	          }
393	        else
394	          {
395	            ret = register_mtddriver("/dev/spiflash", mtd, 0755, NULL);
396	            if (ret < 0)
397	              {
398	                serr("ERROR: register_mtddriver failed: %d\n", ret);
399	              }
400	            else
401	              {
402	                mkdir("/spiflash", 0777);
403	                ret = nx_mount("/dev/spiflash", "/spiflash",
404	                               "littlefs", 0, "autoformat");
405	                if (ret < 0)
406	                  {
407	                    serr("ERROR: Failed to mount LittleFS: %d\n", ret);
408	                  }
409	                else
410	                  {
411	                    _info("bringup: LittleFS mounted at /spiflash\n");
412	                  }
413	              }
414	          }
415	      }
416	  }
417	#endif
